#include <cstddef>
#include <iostream>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) noexcept {
        if (count_ == capacity) {
            return false;
        }
        data_[tail_] = value;
        tail_ = (tail_ + 1) % capacity;
        ++count_;
        return true;
