For S equal to T, the zero-edge walk supplies cost zero. The answer is finite with cost zero unless a negative cycle is reachable from S and can return to S; then it is unbounded. This includes N equal to one with a negative self-loop, which the final test detects even though there are no initial rounds.

Worst-case time is O(N + M + K(N + M′)), where M′ is the number of retained edges. The N term per round matters because `dist.copy()` copies all N entries. Consequently a bound valid for every allowed input is O(N(N + M)), not merely O(NM) when M may be zero. Memory is O(N + M). Each candidate represents at most K edges, so its magnitude is at most K times 10^12, at most 2 × 10^15 under the supplied limits; Python integers preserve exact arithmetic.

Here’s a complete C++17 integer FIFO with all 17 slots usable. Push rejects overflow without changing the queue, and pop rejects an empty queue without changing its output argument. A count distinguishes full from empty; the tests exercise wraparound while unread entries remain queued. This version is not thread-safe.

```cpp
#include <array>
#include <cassert>
#include <cstddef>
#include <iostream>

class BoundedFIFO {
public:
    static constexpr std::size_t capacity = 17;

    bool push(int value) noexcept {
        if (count_ == capacity) return false;
        data_[tail_] = value;
        tail_ = (tail_ + 1) % capacity;
        ++count_;
        return true;
    }

    bool pop(int& value) noexcept {
        if (count_ == 0) return false;
        value = data_[head_];
        head_ = (head_ + 1) % capacity;
        --count_;
        return true;
    }

    std::size_t size() const noexcept { return count_; }
    bool empty() const noexcept { return count_ == 0; }
    bool full() const noexcept { return count_ == capacity; }

private:
    std::array<int, capacity> data_{};
    std::size_t head_ = 0;
    std::size_t tail_ = 0;
    std::size_t count_ = 0;
};

The kernel violates the block-barrier participation invariant: with `valid == 70`, threads 0–69 execute `__syncthreads()` inside the branch, while threads 70–95 skip the load, barrier, and output logic. That is invalid synchronization and can explain the stalled worker, but it does not guarantee a hang on every device. Immediate launch checks detect launch errors, not correct barrier participation or successful asynchronous execution.

Move the barrier outside the conditional, keeping the launch at one block of 96 threads even when `valid == 0`.

```cpp
// worker.cu
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>

#define CUDA_CHECK(call) do { \
    cudaError_t err = (call); \
    if (err != cudaSuccess) { \
        std::fprintf(stderr, "%s: %s\n", #call, cudaGetErrorString(err)); \
        std::exit(EXIT_FAILURE); \
    } \
} while (0)

__global__ void sum_valid(const int* input, int valid,
                         long long* output) {
    __shared__ int entries[96];
    const unsigned t = threadIdx.x;

    if (t < static_cast<unsigned>(valid)) {
        entries[t] = input[t];
    }

    // All 96 threads execute the same block-wide barrier.
    __syncthreads();

    if (t == 0) {
        long long sum = 0;
        for (int i = 0; i < valid; ++i) {
            sum += static_cast<long long>(entries[i]);
        }
        *output = sum;
    }
}

void launch_sum(const int* device_input, int valid,
                long long* device_output, cudaStream_t stream) {
    if (valid < 0 || valid > 96) {
        std::fprintf(stderr, "valid must be between 0 and 96\n");
        std::exit(EXIT_FAILURE);
    }
    // input: at least valid readable integers, ready in this stream.
    // output: one writable long long. Keep both alive until completion.
    sum_valid<<<1, 96, 0, stream>>>(device_input, valid, device_output);
    CUDA_CHECK(cudaGetLastError());
}

int main() {
    int host_input[96];
    for (int i = 0; i < 96; ++i) host_input[i] = i + 1;

    int* device_input = nullptr;
    long long* device_output = nullptr;
    cudaStream_t stream;
    cudaEvent_t complete;
    CUDA_CHECK(cudaStreamCreateWithFlags(&stream, cudaStreamNonBlocking));
    CUDA_CHECK(cudaEventCreateWithFlags(&complete, cudaEventDisableTiming));
    CUDA_CHECK(cudaMalloc(reinterpret_cast<void**>(&device_input),
                          sizeof(host_input)));
    CUDA_CHECK(cudaMalloc(reinterpret_cast<void**>(&device_output),
                          sizeof(long long)));
    CUDA_CHECK(cudaMemcpy(device_input, host_input, sizeof(host_input),
                          cudaMemcpyHostToDevice));

    for (int valid = 0; valid <= 96; ++valid) {
        launch_sum(device_input, valid, device_output, stream);
        CUDA_CHECK(cudaEventRecord(complete, stream));
        CUDA_CHECK(cudaEventSynchronize(complete));

        long long result;
        CUDA_CHECK(cudaMemcpy(&result, device_output, sizeof(result),
                              cudaMemcpyDeviceToHost));
        const long long expected =
            static_cast<long long>(valid) * (valid + 1) / 2;
        if (result != expected) {
            std::fprintf(stderr, "valid=%d: got %lld, expected %lld\n",
                         valid, result, expected);
            std::exit(EXIT_FAILURE);
        }
    }

    CUDA_CHECK(cudaFree(device_input));
    CUDA_CHECK(cudaFree(device_output));
    CUDA_CHECK(cudaEventDestroy(complete));
    CUDA_CHECK(cudaStreamDestroy(stream));
    std::puts("All valid counts from 0 through 96 passed.");
    return EXIT_SUCCESS;
}
